USE bench;
FLUSH STATUS;
SET @t0=NOW(6);
SELECT * FROM ((SELECT 'logs' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_logs a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = FALSE AND a.begin_timestamp >= 1717027200000000000 - 86400000000000 AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100) UNION ALL (SELECT 'logs' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_logs a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = TRUE AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100) UNION ALL (SELECT 'metrics' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_metrics a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = FALSE AND a.begin_timestamp >= 1717027200000000000 - 86400000000000 AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100) UNION ALL (SELECT 'metrics' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_metrics a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = TRUE AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100) UNION ALL (SELECT 'traces' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_traces a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = FALSE AND a.begin_timestamp >= 1717027200000000000 - 86400000000000 AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100) UNION ALL (SELECT 'traces' dataset_name, a.id, a.begin_timestamp, a.end_timestamp, a.size FROM archives_traces a WHERE a.id <= 30000000 AND a.expiration_time > 1735689600 AND a.is_long_span = TRUE AND a.begin_timestamp < 1719619200000000000 AND a.end_timestamp > 1717027200000000000 ORDER BY a.begin_timestamp LIMIT 100)) r ORDER BY begin_timestamp, dataset_name, id LIMIT 100;
SELECT 'E4c streamed warmup' q, TIMESTAMPDIFF(MICROSECOND,@t0,NOW(6))/1000 ms;
SHOW SESSION STATUS WHERE Variable_name='Handler_read_next';
